window.FIXTURES=window.FIXTURES||{};window.FIXTURES["speech"]={"vid":"OEu5o3KvbxM","speaker":"Gitanas Nausėda","role":"President","country":"Lithuania","region":"Europe","url":"https://www.youtube.com/watch?v=OEu5o3KvbxM","date":"20260922","title":"🇱🇹 Lithuania - President Addresses United Nations General Debate, 81st Session | #UNGA","seconds":864,"words":1464,"counts":{"claims":22,"promises":2,"attacks":3},"topics":[{"topic":"Ukraine","share":0.3029,"seconds":262},{"topic":"AI governance","share":0.1585,"seconds":137},{"topic":"Iran","share":0.095,"seconds":82},{"topic":"Lithuania independence","share":0.0935,"seconds":81},{"topic":"Historical remembrance","share":0.0906,"seconds":78},{"topic":"Russia","share":0.076,"seconds":66},{"topic":"Global conflicts","share":0.0717,"seconds":62},{"topic":"UN reform","share":0.0717,"seconds":62},{"topic":"Global security","share":0.0401,"seconds":35}],"timeline":[[2,83,"Lithuania independence"],[85,147,"Global conflicts"],[149,231,"Iran"],[233,311,"Ukraine"],[313,374,"Ukraine"],[375,437,"Ukraine"],[439,499,"Ukraine"],[500,566,"Russia"],[567,632,"AI governance"],[634,706,"AI governance"],[708,770,"UN reform"],[771,849,"Historical remembrance"],[850,885,"Global security"]],"stances":{"Lithuania independence":"Gitanas Nausėda states that Lithuania's return to the global community 35 years ago reaffirmed its commitment to international law and territorial integrity.","Global conflicts":"Gitanas Nausėda states that recent years have brought numerous high-intensity conflicts and geopolitical instability, exacerbated by nuclear ambitions and irresponsible transfers of military goods.","Iran":"Gitanas Nausėda states that Iran's actions constitute a serious threat to peace and calls on the country to halt its nuclear and missile programs.","Ukraine":"Gitanas Nausėda identifies Russia's war of aggression against Ukraine as the greatest threat to the world order and describes its escalation over 12 years.","Russia":"Gitanas Nausėda states that Russia's intensified hybrid attacks, disinformation, and sabotage efforts pose a troubling challenge to information integrity and security.","AI governance":"Gitanas Nausėda states that Lithuania believes AI must not be controlled by authoritarian regimes and is promoting responsible development through the Vilnius Convention.","UN reform":"Gitanas Nausėda expresses gratitude to the Secretary General for his service and asserts that reforming the UN is the correct path, emphasizing that multilateralism is essential to uphold peace and security.","Historical remembrance":"Gitanas Nausėda advocates for a pan-European memorial to victims of 20th-century totalitarian regimes and emphasizes that freedom and justice cannot ultimately be defeated.","Global security":"Gitanas Nausėda calls for collective resistance against the law of the strongest and expresses belief in the capacity to create a more just, secure, and peaceful world."},"claims":[{"t":47,"quote":"35 years ago, Lethia returned to its rightful place in the global community of sovereign","topic":"Lithuania independence","kind":"fact"},{"t":115,"quote":"Recent years have brought us numerous highintensity and far-reaching conflicts that dominate the global affairs on a scale not seen in decades.","topic":"Global conflicts","kind":"fact"},{"t":126,"quote":"We witness geopolitical instability in Europe, the Middle East, and elsewhere.","topic":"Global conflicts","kind":"fact"},{"t":149,"quote":"In recent months, Iran has continued attacking neighboring countries, often through its proxies, while actively inquiring the freedom of navigation in the Strait of Hormuz.","topic":"Iran","kind":"fact"},{"t":164,"quote":"These actions constitute a serious threat to regional and international peace and security.","topic":"Iran","kind":"fact"},{"t":285,"quote":"In the 12 years since the illegal occupation of Crimea, Russia has escalated from clandestine operations and limited warfare in eastern Ukraine to massive military operations, mass killings, and ultimately the largest drone attacks against civilian infrastructure the world has ever seen.","topic":"Ukraine","kind":"fact"},{"t":313,"quote":"The current stage of the war, which began with the full-scale invasion in February 2022, has already lasted longer than the First World War.","topic":"Ukraine","kind":"fact"},{"t":327,"quote":"In the last 55 months, Russia has suffered one and a half million military","topic":"Ukraine","kind":"number"},{"t":336,"quote":"In the last year, it has gained 0.3% of Ukraine's territory at the cost of over 400,000 soldiers killed and wounded.","topic":"Ukraine","kind":"number"},{"t":405,"quote":"How many people will be tortured, sexually assaulted, thrown into dark dungeons, never to see the sunlight again?","topic":"Ukraine","kind":"fact"},{"t":415,"quote":"How many children will be illegally separated from their parents and sent to Russia to suffer","topic":"Ukraine","kind":"fact"},{"t":491,"quote":"In recent months, Russia's war of aggression has led to numerous violations of our airspace by combat drones.","topic":"Ukraine","kind":"fact"},{"t":500,"quote":"Russia has also intensified hybrid attacks, disinformation, and sabotage efforts.","topic":"Russia","kind":"fact"},{"t":560,"quote":"AI has a huge potential for transformation, especially in the field of economy.","topic":"Russia","kind":"fact"},{"t":587,"quote":"My country, Lithuania, strongly believes that the future of AI must not be determined by authoritarian control, technological coercion, or the malicious use of data.","topic":"AI governance","kind":"fact"},{"t":601,"quote":"We are therefore investing in trusted AI cap capabilities, promoting responsible AI deploy deployment and advancing the Wilnos Convention, the world's first legally binding international treaty on artificial intelligence.","topic":"AI governance","kind":"self_credit"},{"t":647,"quote":"With even major uh technology companies sending warning signals that control of AI might slip out of humanity's hands, the time is ripe for collective action.","topic":"AI governance","kind":"fact"},{"t":708,"quote":"I am grateful to the Secretary General, His Excellency Antonio Gutier, for his long lasting service and his focus on reforming the United Nations into a more effective, modern, and responsive This is the correct path to follow.","topic":"UN reform","kind":"fact"},{"t":730,"quote":"No nation can confront today's challenges alone. Aggression cannot win. It is only through multilateralism, solidarity and the unity of all member states that we can uphold peace, security and the rules based international order.","topic":"UN reform","kind":"fact"},{"t":752,"quote":"It is also important to learn from the many lessons of history today to many seem unwilling to recognize and confront the past crimes committed by totalitarian regimes including Soviet This is a fundamental flaw.","topic":"UN reform","kind":"fact"},{"t":776,"quote":"That is why Lethia is promoting the concept of historical remembrance.","topic":"Historical remembrance","kind":"fact"},{"t":782,"quote":"My personal wish is to see the panuropean memorial to all victims of 20th century totalitarian regimes unveiled in Brussels as soon as possible.","topic":"Historical remembrance","kind":"self_credit"}],"promises":[{"t":201,"quote":"We will contribute with our demining capabilities to the international maritime missions in the strait","topic":"Iran","kind":"promise"},{"t":433,"quote":"we all should join our forces to draw Ukraine's victory closer","topic":"Ukraine","kind":"promise"}],"attacks":[{"t":391,"quote":"the Kremlin regime increasingly find itself cornered","topic":"Ukraine","target":"Russia"},{"t":463,"quote":"We cannot tolerate any longer Moscow's colonial aspirations which undermine global food security and driving up fruit prices.","topic":"Ukraine","target":"Russia"},{"t":475,"quote":"Russia's imperial ambitions reach far into Europe, Africa, and Asia.","topic":"Ukraine","target":"Russia"}],"greece":[],"said":[],"pickup":[],"transcript":[{"t":2,"topic":"Lithuania independence","text":"The assembly will hear an address by His Excellency Gitanas Naeta, President of the Republic of Lithuania. I request protocol to escort his excellency and invite him to address the Oh yes, &gt;&gt; your excellency Madame President, excellencies, ladies and gentlemen, 35 years ago, Lethia returned to its rightful place in the global community of sovereign By joining the United Nations, we reaffirmed our strong commitment to the global order based on international law, territorial integrity, state sovereignity, and human It was a glorious moment for a nation well taught by historical experience that freedom and independence cannot be taken for granted."},{"t":85,"topic":"Global conflicts","text":"They must be constantly and consistently Today I am standing here to speak for the same dream that inspired Lithuania in 1991. the vision of the more just, secure, and peaceful world. Today, I am backing up the principles of the United Nations, which sadly are being put under increasing pressure. Recent years have brought us numerous highintensity and far-reaching conflicts that dominate the global affairs on a scale not seen in decades. We witness geopolitical instability in Europe, the Middle East, and elsewhere. It is made worse by growing nuclear ambitions in the Middle East and Asia, as well as the response irresponsible transfer of military related goods, dual use items, and sensitive technologies."},{"t":149,"topic":"Iran","text":"In recent months, Iran has continued attacking neighboring countries, often through its proxies, while actively inquiring the freedom of navigation in the Strait of Hormuz. These actions constitute a serious threat to regional and international peace and security. We reaffirm reaffirm our full solidarity with the Gulf Cooperation Council countries and Jordan. We call on Iran to hold its nuclear and missile programs as well as its collaboration with armed groups across the Middle East. Lithia commends all efforts to find a solution ensuring freedom of navigation. We will contribute with our demining capabilities to the international maritime missions in the strait of As regards the situation in the Gaza Strip, my country supports international efforts to maintain and consolidate the The comprehensive plan to end the Gaza conflict, including the deployment of the temporary international stabilization force, provides the guidelines to follow."},{"t":233,"topic":"Ukraine","text":"Lithuania reiterates the importance of full de demilitarization of non-state armed groups. Humanitarian aid must also be allowed to reach those in need safely and without obstruction. To this day, the two-state solution remains the only way towards a comprehensive, just and lasting peace. In this light, it is crucially important to abstain from any farther actions incompatible with a credible political Ladies and gentlemen, the one conflict that poses the greatest threat to the world order is Russia's war of aggression against Ukraine, supported by its proxies. In the 12 years since the illegal occupation of Crimea, Russia has escalated from clandestine operations and limited warfare in eastern Ukraine to massive military operations, mass killings, and ultimately the largest drone attacks against civilian infrastructure the world has ever seen."},{"t":313,"topic":"Ukraine","text":"The current stage of the war, which began with the full-scale invasion in February 2022, has already lasted longer than the First World War. In the last 55 months, Russia has suffered one and a half million military In the last year, it has gained 0.3% of Ukraine's territory at the cost of over 400,000 soldiers killed and wounded. Yet all these enormous efforts, all that blood and tears basically came to nothing. Ukraine is still standing proudly as an independent state. The Ukrainian language, culture, and national identity are alive and In all but name, Russia has already lost the war."},{"t":375,"topic":"Ukraine","text":"Yet, its leadership does not allow itself to admit defeat, fearing international legal accountability and possible revenge from its own people. As the inevitable approaches, the stakes get higher and the Kremlin regime increasingly find itself cornered. How much more Ukrainian civilian lives will be sacrificed on Russia's war How many people will be tortured, sexually assaulted, thrown into dark dungeons, never to see the sunlight again? How many children will be illegally separated from their parents and sent to Russia to suffer We do not know the answers. Yet, we must all feel the deep pain brought by this brutal and pointless war. And we all should join our forces to draw Ukraine's victory closer."},{"t":439,"topic":"Ukraine","text":"For it is only Ukraine's final victory, safeguarding its sovereignity, independence, and territorial integrity that could ensure the global peace, security, and credibility of the United Nations charter. What we can not allow is a brute force prevailing over international law. We cannot tolerate any longer Moscow's colonial aspirations which undermine global food security and driving up fruit prices. Russia's imperial ambitions reach far into Europe, Africa, and Asia. No country should consider itself immune from this threat. Naturally, Lethania witnesses many dangers up close. In recent months, Russia's war of aggression has led to numerous violations of our airspace by combat drones."},{"t":500,"topic":"Russia","text":"Russia has also intensified hybrid attacks, disinformation, and sabotage efforts. Where Russia advances, opening Pandora's box of new techniques for other hostile actors follow, learning new skills and ideas. Ladies and gentlemen, attacks on information integrity pose an especially troubling challenge to every Disinformation foreign information manipulation and interference and the falsification of history erode trust, restrict civic space and target journalists and human rights defenders. As a result, human rights, democracy and security suffer. This risk is further enhanced by the development of artificial intelligence. As we all know, AI has a huge potential for transformation, especially in the field of economy."},{"t":567,"topic":"AI governance","text":"Whole sectors, including those related to defense and security, might get radically changed or destroyed almost As any instrument, AI is also increasingly used by those seeking to cause harm and destruction. My country, Lithuania, strongly believes that the future of AI must not be determined by authoritarian control, technological coercion, or the malicious use of data. We are therefore investing in trusted AI cap capabilities, promoting responsible AI deploy deployment and advancing the Wilnos Convention, the world's first legally binding international treaty on artificial intelligence. By demonstrating how shared principles can be translated into concrete legal commitments, we hope to contribute significantly to the United Nations global dialogue on AI governance."},{"t":634,"topic":"AI governance","text":"Lethini invites the international community to unite in addressing significant legal, ethical, and strategic challenges posed by artificial With even major uh technology companies sending warning signals that control of AI might slip out of humanity's hands, the time is ripe for collective action. Together, we must ensure that AI serves human dignity, sustainable development, and international security rather than becoming a new instrument of inequality, manipulation, or conflict. At any cost, human accountability, international law, and the peace and security must be Ladies and gentlemen, the credibility of the United Nations depends on its ability to respond firmly to aggression, unlawful conquest, forced deportations, and crimes against humanity and also to coordinate the global response to the growth of AI."},{"t":708,"topic":"UN reform","text":"I am grateful to the Secretary General, His Excellency Antonio Gutier, for his long lasting service and his focus on reforming the United Nations into a more effective, modern, and responsive This is the correct path to follow. There is no other way. No nation can confront today's challenges alone. Aggression cannot win. It is only through multilateralism, solidarity and the unity of all member states that we can uphold peace, security and the rules based international order. It is also important to learn from the many lessons of history today to many seem unwilling to recognize and confront the past crimes committed by totalitarian regimes including Soviet This is a fundamental flaw."},{"t":771,"topic":"Historical remembrance","text":"We must remember the past so as not to repeat That is why Lethia is promoting the concept of historical remembrance. My personal wish is to see the panuropean memorial to all victims of 20th century totalitarian regimes unveiled in Brussels as soon as possible. This one lesson Lithuania having survived and overcome numerous occupations and the waves of repression can share with international community. Freedom can be delayed but it cannot be Justice can be challenged but it cannot be defeated. This I believe is a message that goes far beyond an experience of the single person or the nation. It speaks to the whole humankind united in our shared At a time of growing global uncertainty and power politics, we need even more multilateralism grounded in international law, the UN charter, and universal human rights."},{"t":850,"topic":"Global security","text":"We need to resist the law of the strongest collectively in order not to fall under the yoke separately. The time to act is now. And I believe I want to believe that we have what it takes to make the world a more just, secure, peaceful place to live. Thank On [applause] on behalf of the assembly, I wish to thank the president of the Republic of"}],"compare":[{"topic":"Russia-Ukraine War","share":0.4167,"mean":0.0333,"rank":2,"others":44},{"topic":"Artificial Intelligence","share":0.1743,"mean":0.0498,"rank":13,"others":83},{"topic":"International Law & Order","share":0.123,"mean":0.0601,"rank":35,"others":102},{"topic":"Iran","share":0.1044,"mean":0.0133,"rank":9,"others":25},{"topic":"UN & its reform","share":0.0789,"mean":0.2054,"rank":157,"others":170}]};
